using FormSubmission.AdminPortal.Models; using System.Net.Http.Json; using System.Net.Http.Headers; namespace FormSubmission.AdminPortal.Services;
public class SubmissionApiService { private readonly HttpClient _http; private readonly AuthStateService _auth; public SubmissionApiService(IHttpClientFactory factory, AuthStateService auth){_http=factory.CreateClient("Api");_auth=auth;} private void Bearer(){ if(!string.IsNullOrWhiteSpace(_auth.Token)) _http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",_auth.Token); } public async Task<LoginResponse?> LoginAsync(LoginRequest r){var res=await _http.PostAsJsonAsync("api/auth/login",r); return res.IsSuccessStatusCode?await res.Content.ReadFromJsonAsync<LoginResponse>():null;} public async Task<List<SubmissionDto>> GetAllAsync(string? status){Bearer(); var url=string.IsNullOrWhiteSpace(status)?"api/admin/submissions":$"api/admin/submissions?status={status}"; return await _http.GetFromJsonAsync<List<SubmissionDto>>(url)??new();} public async Task<bool> UpdateStatusAsync(Guid id,string status){Bearer(); var res=await _http.PutAsJsonAsync($"api/admin/submissions/{id}/status", new UpdateStatusRequest(status)); return res.IsSuccessStatusCode;} }